from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        value, write_time = cache[key]
        return t >= write_time + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]

            if key in cache:
                # update existing, not expired
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
                # new entry (either wasn't present or was expired and removed)
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)
                cache.move_to_end(key)

        elif kind == 'get':
            if key in cache and not is_expired(key, t):
                value, write_time = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

